// Restore the full6188 primitive source from a completed original2195 source,
// using the actual B(J_rhs-H*C) transport and both complete original DAGs.
#include "2026-11-14-r150-second-bockstein-common-789f.hpp"
struct SBack {int basis;std::vector<std::pair<uint16_t,uint8_t>> steps;};
struct SFront {int raw,scale;std::vector<std::pair<uint16_t,uint8_t>> steps;};
int main(int argc,char **argv){try{
 if(argc!=8)return 2;auto start=std::chrono::steady_clock::now();auto seconds=[&](){return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};
 sb::Model model(argv[2]);sb::Mix mix(argv[6]);const int nt=mix.count,ns=2195,nb=3333,nraw=6188;BitOps ops;
 std::ifstream cin(argv[1],std::ios::binary),normal(argv[3],std::ios::binary),forward(argv[4],std::ios::binary),backward(argv[5],std::ios::binary);if(!cin||!normal||!forward||!backward)throw std::runtime_error("original transport input");
 if(sb::tag(cin)!="R150SC31"||sb::get(cin,4)!=2195||sb::get(cin,4)!=uint64_t(nt))throw std::runtime_error("completed original source dimensions");int B=sb::get(cin,4),N=sb::get(cin,4),requested=sb::get(cin,4);if(N!=mix.bound||B!=N+96||requested!=N||B>796)throw std::runtime_error("proved original source bound");int P=B-10,PW=P+1;
 std::vector<Row> raw(nraw,Row(5*PW)),beta(nb,Row(5*PW));std::vector<bool> occupied(nraw);int sourceCost=-1;
 for(int i=0;i<ns;i++){int index=sb::get(cin,4),r=sb::get(cin,4),delta=sb::get(cin,2);if(index!=i+1||r!=model.sources[i].raw||delta!=model.delta(r)||occupied[r-1])throw std::runtime_error("actual2195 source map");occupied[r-1]=true;
  for(int j=0;j<nt;j++){int len=sb::get(cin,2),last=0;if(len>B-delta+1)throw std::runtime_error("source degree bound");for(int d=0;d<len;d++){last=sb::get(cin,1);if(last>30)throw std::runtime_error("source field coefficient");BitOps::set(raw[r-1],PW,d*32+j,last);if(last)sourceCost=std::max(sourceCost,delta+d);}if(len&&!last)throw std::runtime_error("source polynomial trailing zero");}
 }sb::tail(cin);
 auto actualDegree=[&](const Row &r){for(int d=P;d>=0;d--){uint32_t nz=0;for(int b=0;b<5;b++)nz|=r[b*PW+d];if(nz){if(nz>>nt)throw std::runtime_error("original transport packed padding");return d;}}return -1;};
 if(sb::tag(normal)!="R150NR31"||sb::get(normal,4)!=2204)throw std::runtime_error("complete original source normal trace");uint64_t normalOps=0,activeOps=0,rhsOps=0;
 for(int i=0;i<2204;i++){
  int r=sb::get(normal,4),target=sb::get(normal,2),steps=sb::get(normal,4);int d=-1;Triple current;
  if(i<ns){if(r!=model.sources[i].raw||target)throw std::runtime_error("normal source trace dictionary");d=actualDegree(raw[r-1]);if(d>=0){current[0]=raw[r-1];BitOps::refresh(current,PW,0);}}
  else if(r||target!=i-ns+2)throw std::runtime_error("original nine trailing trace labels");
  for(int k=0;k<steps;k++){int b=sb::get(normal,2)-1,s=sb::get(normal,1),a=sb::get(normal,1);if(b<0||b>=nb||a<1||a>30)throw std::runtime_error("actual source normal operation");if(d>=0){if(d+s>P)throw std::runtime_error("prebasis source compensation degree");auto rep=ops.rep[31-a];BitOps::add(beta[b],PW,s,current[rep.c],PW,0,d+1,rep.rot,rep.neg);activeOps++;}normalOps++;}
  if((i+1)%500==0||i+1==2204)std::cout<<"{\"phase\":\"actual-original-prebasis-minus-HC\",\"sourceRows\":"<<i+1<<",\"elapsedSeconds\":"<<seconds()<<"}\n"<<std::flush;
 }sb::tail(normal);if(normalOps!=25305683)throw std::runtime_error("complete original normal operation count");
 for(const auto &f:mix.families){
  std::ifstream in(f.trace,std::ios::binary);if(sb::tag(in)!="R150NR31"||sb::get(in,4)!=uint64_t(f.count))throw std::runtime_error("actual RHS trace dimensions");
  for(int i=0;i<f.count;i++){int r=sb::get(in,4),label=sb::get(in,2),steps=sb::get(in,4);if(r||label!=f.labels[i])throw std::runtime_error("actual combined RHS trace label");int length=0;for(auto &p:f.poly[i])length=std::max(length,int(p.size()));Triple multiplier;if(length){multiplier[0].resize(5*length);for(int j=0;j<nt;j++)for(int d=0;d<int(f.poly[i][j].size());d++)BitOps::set(multiplier[0],length,d*32+j,f.poly[i][j][d]);BitOps::refresh(multiplier,length,0);}
   for(int k=0;k<steps;k++){int b=sb::get(in,2)-1,s=sb::get(in,1),a=sb::get(in,1);if(b<0||b>=nb||a<1||a>30)throw std::runtime_error("actual combined RHS trace coefficient");if(length){if(s+length>PW)throw std::runtime_error("actual RHS trace source cost");auto rep=ops.rep[a];BitOps::add(beta[b],PW,s,multiplier[rep.c],length,0,length,rep.rot,rep.neg);}rhsOps++;}
  }sb::tail(in);
 }
 if(sb::tag(backward)!="R150RJ31"||sb::get(backward,4)!=3333)throw std::runtime_error("backward prebasis dimensions");std::vector<SBack> back(nb);std::vector<bool> seen(nb);
 for(auto &r:back){r.basis=sb::get(backward,2)-1;int n=sb::get(backward,4);if(r.basis<0||r.basis>=nb||seen[r.basis])throw std::runtime_error("backward actual prebasis map");seen[r.basis]=true;r.steps.resize(n);for(auto &x:r.steps){x.first=sb::get(backward,2);x.second=sb::get(backward,1);if(x.first<1||x.first>nb||x.first==r.basis+1||x.second<1||x.second>30)throw std::runtime_error("backward operation");}}sb::tail(backward);
 uint64_t bops=0,fops=0;
 for(auto it=back.rbegin();it!=back.rend();it++){int d=actualDegree(beta[it->basis]);Triple current;if(d>=0){current[0]=beta[it->basis];BitOps::refresh(current,PW,0);}for(auto [basis,a]:it->steps){if(d>=0){auto rep=ops.rep[31-a];BitOps::add(beta[basis-1],PW,0,current[rep.c],PW,0,d+1,rep.rot,rep.neg);}bops++;}}
 if(sb::tag(forward)!="R150PB31"||sb::get(forward,4)!=3333)throw std::runtime_error("forward prebasis dimensions");std::vector<SFront> front(nb);
 for(int i=0;i<nb;i++){auto &r=front[i];r.raw=sb::get(forward,4);r.scale=sb::get(forward,1);int n=sb::get(forward,4);if(r.raw!=model.pre[i].raw||r.scale<1||r.scale>30)throw std::runtime_error("forward original source map");r.steps.resize(n);for(auto &x:r.steps){x.first=sb::get(forward,2);x.second=sb::get(forward,1);if(x.first<1||x.first>i||x.second<1||x.second>30)throw std::runtime_error("forward original dependency");}}sb::tail(forward);
 for(int i=nb-1;i>=0;i--){auto &r=front[i];int d=actualDegree(beta[i]);Triple current;if(d>=0){current[0]=beta[i];ops.multiple(current[0],PW,0,r.scale);BitOps::refresh(current,PW,0);BitOps::add(raw[r.raw-1],PW,0,current[0],PW,0,d+1,0,0);}for(auto [basis,a]:r.steps){if(d>=0){auto rep=ops.rep[31-a];BitOps::add(beta[basis-1],PW,0,current[rep.c],PW,0,d+1,rep.rot,rep.neg);}fops++;}}
 if(bops!=1010703||fops!=782976)throw std::runtime_error("complete original prebasis DAG operation counts");for(auto &s:model.pre){if(occupied[s.raw-1])throw std::runtime_error("prebasis source overlap");occupied[s.raw-1]=true;}if(std::count(occupied.begin(),occupied.end(),true)!=5528)throw std::runtime_error("complete selected source set");
 std::string prefix=argv[7];std::ofstream out(prefix+"-primitive-source-mod31.bin",std::ios::binary);out.write("R150PS31",8);for(int a:{31,31,6188,nt,B})u32(out,a);for(int a:mix.labels)u16(out,a);std::vector<int> costs(nt,-1);uint64_t nonzero=0;int maxdegree=-1,rows=0;
 for(int r=1;r<=6188;r++){model.rowHeader(out,r);int delta=model.delta(r),rd=-1;for(int j=0;j<nt;j++){int d=P;while(d>=0&&!BitOps::get(raw[r-1],PW,d*32+j))d--;u16(out,d+1);for(int k=0;k<=d;k++){int a=BitOps::get(raw[r-1],PW,k*32+j);u16(out,a);if(a){if(!occupied[r-1]||k+delta>B)throw std::runtime_error("restored original source cost");costs[j]=std::max(costs[j],k+delta);nonzero++;}}rd=std::max(rd,d);}rows+=rd>=0;maxdegree=std::max(maxdegree,rd);}
 out.close();if(!out)throw std::runtime_error("full primitive source output failure");std::ofstream meta(prefix+"-original-transport.json");
 meta<<"{\"format\":\"r150-actual-prebasis-original-source-transport-v1\",\"status\":\"completed\",\"prime\":31,\"targetCount\":"<<nt<<",\"provedSourceCostBound\":"<<B<<",\"actualNormalSourceMaximumCost\":"<<sourceCost<<",\"originalRows\":6188,\"selectedOriginalRows\":5528,\"normalOperations\":"<<normalOps<<",\"activeNormalOperations\":"<<activeOps<<",\"combinedRHSOperations\":"<<rhsOps<<",\"backwardOperations\":"<<bops<<",\"forwardOperations\":"<<fops<<",\"fullActualPrebasisTransport\":true,\"higherModulusProductVerified\":false,\"nonzeroRawRows\":"<<rows<<",\"nonzeroCoefficients\":"<<nonzero<<",\"maximumCoefficientDegree\":"<<maxdegree<<",\"sourceCosts\":";sb::array(meta,costs);meta<<",\"elapsedSeconds\":"<<seconds()<<"}\n";meta.close();if(!meta)throw std::runtime_error("transport metadata failure");
 std::cout<<"{\"status\":\"original-source-transport-complete\",\"targetCount\":"<<nt<<",\"sourceCosts\":";sb::array(std::cout,costs);std::cout<<",\"elapsedSeconds\":"<<seconds()<<"}\n";return 0;
}catch(const std::exception &e){std::cerr<<"SECOND_BOCKSTEIN_ORIGINAL_TRANSPORT_FAILED "<<e.what()<<"\n";return 1;}}
